package io.fireflysoftware.core.banking.cards.core.services.card.enrollment.store;

import static org.junit.jupiter.api.Assertions.*;
import io.fireflysoftware.core.banking.cards.core.services.card.enrollment.*;
import io.fireflysoftware.core.banking.cards.core.services.card.enrollment.impl.*;
import java.util.concurrent.atomic.AtomicInteger;
import org.fireflyframework.kernel.audit.AuditActor;
import org.junit.jupiter.api.Test;
import reactor.core.publisher.Mono;

/** Ordinary genuine mapper/root composition; authority/native replies remain networkless models. */
class ManagedCardReservationAuditTest {
    static ManagedCardReservationAuditAdmission admission(ManagedCardAuditFixture f){return (principal,authorization,graph)->Mono.just(new ManagedCardReservationAuditAdmission.Observation(new AuditActor(principal.issuer(),principal.subject(),"cards-client",principal.tenantId(),"sandbox-staff",ManagedCardAuditFixture.id(2)),authorization.actorId(),"sandbox-audit-policy-1",f.now.plusSeconds(4)));}
    static ManagedCardReservationAudit audit(ManagedCardAuditFixture f,ManagedCardReservationAuditAdmission admission){return new ManagedCardReservationAuditImpl(f.resources,f.client,f.template,f.manager,f.principals,f,admission,f.clock,f.nanos,()->ManagedCardAuditFixture.id(f.ids.incrementAndGet()));}
    static ManagedCardEnrollmentService service(ManagedCardAuditFixture f,ManagedCardReservationAudit audit){return new ManagedCardEnrollmentServiceImpl(f.principals,f,f.command,f.reader,f.clock,f.nanos,()->ManagedCardAuditFixture.id(f.ids.incrementAndGet()),audit);}
    @Test void actualReservationAndPermanentAuditShareOneLeaseAndCommit(){var f=new ManagedCardAuditFixture();var result=service(f,audit(f,admission(f))).reserve(ManagedCardAuditFixture.id(4),f.request()).block();assertNotNull(result);assertEquals(8,f.driver.tables.values().stream().mapToInt(java.util.List::size).sum());assertEquals(1,f.driver.creates);assertEquals(1,f.driver.commits);assertEquals(0,f.driver.rollbacks);assertEquals(1,f.driver.auditEnters);assertEquals(1,f.driver.auditPairs);assertEquals(1,f.driver.tables.get("audit_event").size());assertEquals(1,f.driver.tables.get("audit_outbox").size());}
    @Test void exactReplayRetainsOriginalAuditWithoutFurtherPermanentWrites(){var f=new ManagedCardAuditFixture();var service=service(f,audit(f,admission(f)));var first=service.reserve(ManagedCardAuditFixture.id(4),f.request()).block();int writes=f.driver.writes;assertEquals(first,service.reserve(ManagedCardAuditFixture.id(4),f.request()).block());assertEquals(writes,f.driver.writes);assertEquals(2,f.driver.auditPairs);assertEquals(2,f.driver.commits);}
    @Test void actualAuditZeroCountRollsBackTheFiveBusinessRows(){var f=new ManagedCardAuditFixture();f.driver.failAuditCount=true;var error=assertThrows(ManagedCardEnrollmentException.class,()->service(f,audit(f,admission(f))).reserve(ManagedCardAuditFixture.id(4),f.request()).block());assertTrue(error.transactionFacts().rollbackAcknowledged());assertEquals(0,f.driver.commits);assertTrue(f.driver.tables.isEmpty());assertEquals(1,f.driver.rollbacks);}
    @Test void withdrawnMandatoryProfileRollsBackBusinessAndAudit(){var f=new ManagedCardAuditFixture();var checks=new AtomicInteger();var delegate=admission(f);ManagedCardReservationAuditAdmission admission=(p,a,g)->checks.incrementAndGet()==1?delegate.requireCurrent(p,a,g):Mono.empty();assertThrows(ManagedCardEnrollmentException.class,()->service(f,audit(f,admission)).reserve(ManagedCardAuditFixture.id(4),f.request()).block());assertTrue(f.driver.tables.isEmpty());assertEquals(1,f.driver.rollbacks);assertEquals(0,f.driver.commits);}
    @Test void legacyReservationCannotBeBackfilledAsOriginalAudit(){var f=new ManagedCardAuditFixture();f.legacy().reserve(ManagedCardAuditFixture.id(4),f.request()).block();var original=f.driver.copy();assertThrows(ManagedCardEnrollmentException.class,()->service(f,audit(f,admission(f))).reserve(ManagedCardAuditFixture.id(4),f.request()).block());assertEquals(original,f.driver.tables);assertFalse(f.driver.tables.containsKey("audit_event"));assertEquals(1,f.driver.commits);assertEquals(1,f.driver.rollbacks);}
    @Test void auditFromAnotherSessionIsRejectedAtComposition(){var f=new ManagedCardAuditFixture();var other=new ManagedCardAuditFixture();assertThrows(IllegalArgumentException.class,()->service(f,audit(other,admission(other))));assertEquals(0,f.driver.creates);assertEquals(0,other.driver.creates);}

    @Test void auditedConstructorCannotSilentlyAcceptMissingAudit(){var f=new ManagedCardAuditFixture();assertThrows(NullPointerException.class,()->service(f,null));assertEquals(0,f.driver.creates);}
    @Test void directCallOutsideOriginalRootRefusesBeforeAnySql(){var f=new ManagedCardAuditFixture();var authorization=f.authorizeReservation(f.principal.get(),ManagedCardAuditFixture.id(4),f.request()).block();var graph=ManagedCardReservationFactory.create(authorization.selection(),f.request(),ManagedCardAuditFixture.id(50),ManagedCardAuditFixture.id(51),ManagedCardAuditFixture.id(52),ManagedCardAuditFixture.id(53),authorization.accountFenceReceiptId(),f.now.toEpochMilli());assertThrows(RuntimeException.class,()->audit(f,admission(f)).append(null,ManagedCardAuditFixture.id(77),authorization,graph,ManagedCardReservationAudit.BusinessDisposition.NEW_RESERVATION).block());assertEquals(0,f.driver.creates);assertEquals(0,f.driver.writes);}
    @Test void readerRecoveryDoesNotInventMutationAudit(){var f=new ManagedCardAuditFixture();var service=service(f,audit(f,admission(f)));var original=service.reserve(ManagedCardAuditFixture.id(4),f.request()).block();f.readerDriver.tables=f.driver.copy();var recovered=service.recover(ManagedCardAuditFixture.id(4),new io.fireflysoftware.core.banking.cards.interfaces.dtos.card.enrollment.ManagedCardProviderContracts.RecoveryRequest(ManagedCardAuditFixture.id(11),0L)).block();assertEquals(original,recovered);assertEquals(0,f.readerDriver.auditEnters);assertEquals(0,f.readerDriver.writes);}
    @Test void changedProfileActorCannotBecomeOriginalReservationAudit(){var f=new ManagedCardAuditFixture();var delegate=admission(f);ManagedCardReservationAuditAdmission changed=(p,a,g)->delegate.requireCurrent(p,a,g).map(o->new ManagedCardReservationAuditAdmission.Observation(new AuditActor(o.actor().issuer(),"different-current-subject",o.actor().clientId(),o.actor().platformTenantId(),o.actor().staffRealm(),o.actor().staffId()),o.domainActorId(),o.policyRevision(),o.validUntil()));assertThrows(ManagedCardEnrollmentException.class,()->service(f,audit(f,changed)).reserve(ManagedCardAuditFixture.id(4),f.request()).block());assertTrue(f.driver.tables.isEmpty());assertEquals(0,f.driver.auditEnters);assertEquals(1,f.driver.rollbacks);}

    @Test void actualAuditTwoOrMissingCountAlsoRollBackAllBusinessRows(){for(int kind=0;kind<2;kind++){var f=new ManagedCardAuditFixture();f.driver.failAuditCount=true;f.driver.auditCount=2;f.driver.missingAuditCount=kind==1;var error=assertThrows(ManagedCardEnrollmentException.class,()->service(f,audit(f,admission(f))).reserve(ManagedCardAuditFixture.id(4),f.request()).block());assertTrue(error.transactionFacts().rollbackAcknowledged());assertEquals(1,f.driver.auditEnters);assertEquals(6,f.driver.writes);assertTrue(f.driver.tables.isEmpty());assertEquals(0,f.driver.commits);}}
    @Test void caughtAuditRefusalStillMarksTheActualOwnerRootRollbackOnly(){var f=new ManagedCardAuditFixture();var authorized=f.authorizeReservation(f.principal.get(),ManagedCardAuditFixture.id(4),f.request()).block();var graph=ManagedCardReservationFactory.create(authorized.selection(),f.request(),ManagedCardAuditFixture.id(50),ManagedCardAuditFixture.id(51),ManagedCardAuditFixture.id(52),ManagedCardAuditFixture.id(53),authorized.accountFenceReceiptId(),f.now.toEpochMilli());var adapter=audit(f,(p,a,g)->Mono.empty());var budget=org.fireflyframework.core.transaction.R2dbcOperationBudget.observed(f.now,f.now.plusSeconds(5),f.nanos.getAsLong(),java.time.Duration.ofSeconds(5),f.clock,f.nanos);var done=f.command.transactions().execute(budget,new org.springframework.transaction.support.DefaultTransactionDefinition(),scope->f.command.repository().appendReserved(graph).then(adapter.append(scope,ManagedCardAuditFixture.id(77),authorized,graph,ManagedCardReservationAudit.BusinessDisposition.NEW_RESERVATION)).thenReturn("business").onErrorReturn("caught")).block();assertFalse(done.transactionFacts().commitAcknowledged());assertTrue(done.transactionFacts().rollbackAcknowledged());assertTrue(f.driver.tables.isEmpty());assertEquals(0,f.driver.commits);}
    @Test void completedOriginalScopeCannotBeReusedForAnotherAppend(){var f=new ManagedCardAuditFixture();var captured=new java.util.concurrent.atomic.AtomicReference<org.fireflyframework.core.transaction.RootTransactionScope>();var budget=org.fireflyframework.core.transaction.R2dbcOperationBudget.observed(f.now,f.now.plusSeconds(5),f.nanos.getAsLong(),java.time.Duration.ofSeconds(5),f.clock,f.nanos);f.command.transactions().execute(budget,new org.springframework.transaction.support.DefaultTransactionDefinition(),scope->{captured.set(scope);return Mono.just("done");}).block();var authorized=f.authorizeReservation(f.principal.get(),ManagedCardAuditFixture.id(4),f.request()).block();var graph=ManagedCardReservationFactory.create(authorized.selection(),f.request(),ManagedCardAuditFixture.id(50),ManagedCardAuditFixture.id(51),ManagedCardAuditFixture.id(52),ManagedCardAuditFixture.id(53),authorized.accountFenceReceiptId(),f.now.toEpochMilli());assertThrows(RuntimeException.class,()->audit(f,admission(f)).append(captured.get(),ManagedCardAuditFixture.id(77),authorized,graph,ManagedCardReservationAudit.BusinessDisposition.NEW_RESERVATION).block());assertEquals(1,f.driver.creates);assertEquals(0,f.driver.auditEnters);assertEquals(0,f.driver.writes);}
}
